package ca.yorku.eecs3311.coursepilot.domain.model;
import jakarta.persistence.*; import java.time.Instant; import java.util.ArrayList; import java.util.List;
@Entity @Table(name="quiz_attempts") public class QuizAttempt { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="quiz_id",nullable=false) private Quiz quiz; @Column(nullable=false) private Instant startedAt; private Instant completedAt; @Column(nullable=false) private int correctCount; @Column(nullable=false) private int totalCount; @OneToMany(mappedBy="attempt",cascade=CascadeType.ALL,orphanRemoval=true) private List<QuizResponse> responses=new ArrayList<>(); protected QuizAttempt(){} public QuizAttempt(Quiz q,int total){quiz=q;totalCount=total;startedAt=Instant.now();} public Long getId(){return id;} public Quiz getQuiz(){return quiz;} public Instant getStartedAt(){return startedAt;} public Instant getCompletedAt(){return completedAt;} public int getCorrectCount(){return correctCount;} public int getTotalCount(){return totalCount;} public List<QuizResponse> getResponses(){return responses;} public void finish(int correct){correctCount=correct;completedAt=Instant.now();} public void addResponse(QuizResponse r){responses.add(r);} }
